from qgis.PyQt.QtWidgets import QAction, QDockWidget, QApplication
from qgis.PyQt.QtCore import Qt, QEvent, QPointF
from qgis.PyQt.QtGui import QMouseEvent

canvas = iface.mapCanvas()
vp = canvas.viewport()
pt = QPointF(vp.rect().center())
gpt = QPointF(vp.mapToGlobal(pt.toPoint()))

for etype in (QEvent.Type.MouseButtonPress, QEvent.Type.MouseButtonRelease):
    ev = QMouseEvent(etype, pt, gpt, Qt.MouseButton.LeftButton, Qt.MouseButton.LeftButton, Qt.KeyboardModifier.NoModifier)
    QApplication.sendEvent(vp, ev)
QApplication.processEvents()

mw = iface.mainWindow()
dock = mw.findChild(QDockWidget, 'AdvancedDigitizingTools')
out = {}
for a in dock.findChildren(QAction):
    if a.objectName() in ('mParallelAction','mPerpendicularAction','mEnableAction'):
        out[a.objectName()] = {'enabled': a.isEnabled(), 'checked': a.isChecked()}
result = out
"}

