from qgis.PyQt.QtWidgets import QAction, QDockWidget

mw = iface.mainWindow()
dock = mw.findChild(QDockWidget, 'AdvancedDigitizingTools')
out = {}
for a in dock.findChildren(QAction):
    if a.objectName() == 'mParallelAction':
        out['before'] = {'enabled': a.isEnabled(), 'checked': a.isChecked()}
        a.setEnabled(True)   # UIゲートを一時解除
        a.trigger()
        out['after'] = {'enabled': a.isEnabled(), 'checked': a.isChecked()}
        break
result = out
"}
